    --bg-color: #121212;
    --surface-color: #1e1e1e;
    --text-primary: #ffffff;
    --text-secondary: #e0e0e0;
    --accent-color: #bb86fc;
    --accent-hover: #9965f4;
    --focus-ring: #bb86fc;
}

body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
}

/* Accessibility: Visually Hidden but available to screen readers */
.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Accessibility: Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: #000;
    padding: 8px 16px;
    z-index: 1000;
    font-weight: bold;
    text-decoration: none;
    transition: top 0.2s;
}

.skip-link:focus {
    top: 0;
    outline: 2px solid #fff;
    outline-offset: -2px;
}

/* Focus Management */
a:focus-visible, 
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 4px;
    border-radius: 4px;
}

/* Header */
header {
    background-color: var(--surface-color);
    padding: 1rem 2rem;
    border-bottom: 1px solid #333;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--text-primary);
    text-decoration: none;
}

nav ul {
    list-style: none;
    display: flex;
    gap: 2rem;
    margin: 0;
    padding: 0;
}

nav a {
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 500;
}

nav a:hover {
    color: var(--accent-color);
    text-decoration: underline;
}

.cart button {
    background: none;
    border: none;
    color: var(--text-primary);
    font-size: 1rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem;
}

/* Typography & Layout */
main {
    padding: 0;
}

section {
    padding: 4rem 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

section h2 {
    font-size: 2rem;
    margin-top: 0;
    margin-bottom: 2rem;
    border-bottom: 2px solid #333;
    padding-bottom: 0.5rem;
}

/* Hero */
.hero {
    background: linear-gradient(rgba(18, 18, 18, 0.8), rgba(18, 18, 18, 1)), url('https://images.unsplash.com/photo-1618354691373-d851c5c3a990?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80') center/cover;
    text-align: center;
    padding: 8rem 2rem;
    max-width: none;
}

.hero h1 {
    font-size: 3rem;
    margin: 0 0 1rem;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.cta-button {
    display: inline-block;
    background-color: var(--accent-color);
    color: #000;
    padding: 0.75rem 1.5rem;
    text-decoration: none;
    font-weight: bold;
    border-radius: 4px;
    transition: background-color 0.2s;
}

.cta-button:hover {
    background-color: var(--accent-hover);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    padding: 1rem;
    text-align: center;
    border: 1px solid #333;
    display: flex;
    flex-direction: column;
}

.product-card img {
    width: 100%;
    height: auto;
    border-radius: 4px;
    background-color: #2a2a2a;
    aspect-ratio: 1 / 1;
    object-fit: cover;
}

.product-card h3 {
    margin: 1rem 0 0.5rem;
    font-size: 1.25rem;
}

.product-card .price {
    font-weight: bold;
    color: var(--accent-color);
    font-size: 1.1rem;
    margin-bottom: 1rem;
}

.product-card button {
    width: 100%;
    padding: 0.75rem;
    background-color: transparent;
    border: 1px solid var(--accent-color);
    color: var(--accent-color);
    border-radius: 4px;
    cursor: pointer;
    font-weight: bold;
    transition: all 0.2s;
    margin-top: auto;
}

.product-card button:hover {
    background-color: var(--accent-color);
    color: #000;
}

/* Deals */
.deal-banner {
    background-color: var(--surface-color);
    padding: 3rem;
    border-radius: 8px;
    text-align: center;
    border: 1px solid var(--accent-color);
}

.deal-banner h3 {
    font-size: 2rem;
    margin: 0 0 1rem;
    color: var(--accent-color);
}

.deal-banner p {
    font-size: 1.1rem;
}

/* Editorial */
.article-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #333;
}

.editorial-card img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    background-color: #2a2a2a;
}

.editorial-card .content {
    padding: 1.5rem;
}

.editorial-card h3 {
    margin: 0 0 1rem;
    font-size: 1.25rem;
}

.editorial-card p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
}

.editorial-card a {
    color: var(--accent-color);
    text-decoration: none;
    font-weight: bold;
}

.editorial-card a:hover {
    text-decoration: underline;
}

/* Footer */
footer {
    background-color: var(--surface-color);
    padding: 2rem;
    text-align: center;
    border-top: 1px solid #333;
    margin-top: 2rem;
    color: var(--text-secondary);
}

/* Responsive */
@media (max-width: 768px) {
    .header-container {
        flex-direction: column;
        gap: 1rem;
    }
    nav ul {
        flex-wrap: wrap;
        justify-content: center;
    }
}
