}

.deal-banner p {
    font-size: 1.1rem;
}

/* Editorial */
.article-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background-color: var(--surface-color);
    border-radius: 8px;
