const { chromium } = require('playwright');
const axe = require('axe-core');
const fs = require('fs');

(async () => {
    try {
        const browser = await chromium.launch();
        const page = await browser.newPage();

        // Read index.html content
        const html = fs.readFileSync('index.html', 'utf-8');

        // Setup local web server or file:// protocol to also load CSS/JS, 
        // but setContent might not load local CSS/JS properly without a proper base URL or loading them inline.
        // Wait, for accurate testing, let's load it via file URL.
        const path = require('path');
        const fileUrl = 'file://' + path.resolve('index.html');
        await page.goto(fileUrl, { waitUntil: 'load' });

        // Inject axe
        await page.evaluate(axe.source);

        // Run axe
        const results = await page.evaluate(async () => {
            return await window.axe.run();
        });

        await browser.close();

        const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
        const bp = results.violations.filter(v => v.tags.includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        process.exit(wcag.length ? 1 : 0);
    } catch (e) {
        console.error(e);
        process.exit(1);
    }
